			if (cipherChar > 122){ 
				cipherChar = 97 + (cipherChar - 123);		 
			} 
			encryptedMessage += String.fromCharCode(cipherChar); 
		} else { 
			encryptedMessage += String.fromCharCode(charCode); 
		} 
	} 
